import { test, expect } from '@playwright/test';

test.describe('Edit Task Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should display the Edit button for an existing task', async ({ page }) => {
    const taskName = 'Sample Task';
    await expect(page.getByText(taskName)).toBeVisible();
    await expect(page.getByRole('button', { name: 'Edit' })).toBeVisible();
  });

  test('should allow user to edit an existing task', async ({ page }) => {
    const taskName = 'Sample Task';
    await page.getByText(taskName).click();
    await page.getByRole('button', { name: 'Edit' }).click();

    const newTaskName = 'Updated Task';
    await page.getByLabel('Task Name').fill(newTaskName);
    await page.getByRole('button', { name: 'Save' }).click();

    await expect(page.getByText(newTaskName)).toBeVisible();
    await expect(page.getByText(taskName)).not.toBeVisible();
  });
});
